impl Solution{pub fn reorder_list(head:&mut Option<Box<ListNode>>){let mut v=vec![];let mut p=head.take();while let Some(mut n)=p{p=n.next.take();v.push(n.val);}let mut o=vec![];let(mut l,mut r)=(0usize,v.len().saturating_sub(1));while l<=r&&l<v.len(){o.push(v[l]);if l<r{o.push(v[r]);}l+=1;if r==0{break}r-=1;}let mut h=None;for &x in o.iter().rev(){let mut n=Box::new(ListNode::new(x));n.next=h;h=Some(n);}*head=h;}}
